/**
 * The one error type of the core. `reason` is the text a host logs or
 * shows; the conformance vectors compare it exactly. (Not `message`: that
 * name clashes with `Throwable.message` in the Kotlin bindings.)
 */
sealed class CoreException: kotlin.Exception() {
    
    class InvalidInput(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.InvalidInput(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.InvalidInput -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * A date action of spec §4. The comment on each variant names its spec ID.
 */
sealed class DateAction {
    
    /**
     * A1. Put the task on Today. Replaces its When date (I1).
     */
    data class PutOnToday(
        val `mode`: RescheduleMode) : DateAction() {
        companion object
    }
    
    /**
     * A2. Plan the task for `day`. A day on or before today is A1.
     */
    data class ScheduleFor(
        val `day`: kotlin.String, 
        val `mode`: RescheduleMode) : DateAction() {
        companion object
    }
    
    /**
     * A3. Take the task off Today. An arrived When date or deadline goes too
     * (decision Q2).
     */
    object RemoveFromToday : DateAction()
    
    
    /**
     * A4. A3 when the task is on Today (R2), else A1.
     */
    data class ToggleToday(
        val `mode`: RescheduleMode) : DateAction() {
        companion object
    }
    
    /**
     * A5. Clear the When date. The deadline stays (I5).
     */
    object ClearWhenDate : DateAction()
    
    
    /**
     * A6. Clear When: When date, deadline, pin and time slot all go.
     */
    object ClearWhen : DateAction()
    
    
    /**
     * A7 (a day) and A8 (none). Set or clear the deadline.
     */
    data class SetDeadline(
        val `day`: kotlin.String?) : DateAction() {
        companion object
    }
    
    /**
     * A9. Set or clear the time slot. A time with no day pins the task.
     */
    data class SetTimeSlot(
        val `startTime`: kotlin.String?, 
        val `durationMinutes`: kotlin.Int?, 
        val `timeZone`: kotlin.String?) : DateAction() {
        companion object
    }
    
    /**
     * A11. File the task from the triage band: A1, unless the task has a
     * future When date, which it keeps.
     */
    object FileFromTriage : DateAction()
    
    

    
    companion object
}

