sealed class PullPageDecision {
    
    /**
     * Apply the page and its cursor in one transaction; the pull is done.
     */
    object Apply : PullPageDecision()
    
    
    /**
     * Apply the page, then pull again from `next_cursor`.
     */
    data class ApplyAndContinue(
        val `nextCursor`: kotlin.Long) : PullPageDecision() {
        companion object
    }
    
    /**
     * Clear the remote cache and cursor, keep local rows and queued ops, pull from 0.
     */
    object Reset : PullPageDecision()
    
    
    /**
     * Stop the sync and surface the reason.
     */
    data class Fail(
        val `reason`: kotlin.String) : PullPageDecision() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePullPageDecision : FfiConverterRustBuffer<PullPageDecision>{
    override fun read(buf: ByteBuffer): PullPageDecision {
        return when(buf.getInt()) {
            1 -> PullPageDecision.Apply
            2 -> PullPageDecision.ApplyAndContinue(
                FfiConverterLong.read(buf),
                )
            3 -> PullPageDecision.Reset
            4 -> PullPageDecision.Fail(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PullPageDecision) = when(value) {
        is PullPageDecision.Apply -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is PullPageDecision.ApplyAndContinue -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterLong.allocationSize(value.`nextCursor`)
            )
        }
        is PullPageDecision.Reset -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is PullPageDecision.Fail -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: PullPageDecision, buf: ByteBuffer) {
        when(value) {
            is PullPageDecision.Apply -> {
                buf.putInt(1)
                Unit
            }
            is PullPageDecision.ApplyAndContinue -> {
                buf.putInt(2)
                FfiConverterLong.write(value.`nextCursor`, buf)
                Unit
            }
            is PullPageDecision.Reset -> {
                buf.putInt(3)
                Unit
            }
            is PullPageDecision.Fail -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
